n, err := rand.Int(rand.Reader, big.NewInt(100))
if err != nil {
	panic(err)
}
data := struct {
	Message string
	Number  *big.Int
}{Message: "Hello World", Number: n}
if err := template.New("hello").Execute(os.Stdout, data); err != nil {
	panic(err)
}

